<#
.SYNOPSIS
    Self-extracting master builder script for the "macify-windows" repository.
.DESCRIPTION
    Generates the entire production-ready macify-windows repository structure
    and all complete source files locally in one single automated run.
#>

[CmdletBinding()]
param(
    [string]$TargetDirectory = (Join-Path (Get-Location) "macify-windows")
)

Write-Host "Generating macify-windows repository at: $TargetDirectory" -ForegroundColor Cyan

$payload = [ordered]@{
    "install.ps1" = ""
    "LICENSE" = ""
    "README.md" = ""
    "uninstall.ps1" = ""
    "configs/ahk/mac-shortcuts.ahk" = ""
    "configs/cursors/install-cursors.ps1" = ""
    "configs/rainmeter/MacTopBar/MacTopBar.ini" = ""
    "configs/translucenttb/settings.json" = ""
    "scripts/assets.ps1" = ""
    "scripts/backup.ps1" = ""
    "scripts/common.ps1" = ""
    "scripts/dependencies.ps1" = ""
    "scripts/win11-explorer.ps1" = ""
    "scripts/win11-shell.ps1" = ""
}

foreach ($item in $payload.GetEnumerator()) {
    $relPath = $item.Key.Replace("/", [System.IO.Path]::DirectorySeparatorChar)
    $destFile = Join-Path $TargetDirectory $relPath
    $destDir  = Split-Path -Parent $destFile
    if (-not (Test-Path -Path $destDir)) {
        New-Item -ItemType Directory -Force -Path $destDir | Out-Null
    }
    $bytes = [Convert]::FromBase64String($item.Value)
    [System.IO.File]::WriteAllBytes($destFile, $bytes)
    Write-Host "Created: $destFile" -ForegroundColor Green
}

Write-Host "
macify-windows repository build completed successfully." -ForegroundColor Green
